package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RealMatrixImpl.operate(double[] v)
 */
public class RealMatrixImpl_operate_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testOperateWithValidMatrixAndVector() {
        // Matrix:
        // [ 1.0, 2.0 ]
        // [ 3.0, 4.0 ]
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        double[] v = {0.5, 1.5};

        // Expected result:
        // [ 1.0*0.5 + 2.0*1.5 ] = [ 0.5 + 3.0 ] = [ 3.5 ]
        // [ 3.0*0.5 + 4.0*1.5 ] = [ 1.5 + 6.0 ] = [ 7.5 ]
        double[] expected = {3.5, 7.5};
        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test
    public void testOperateWithRectangularMatrix() {
        // Matrix 3x2:
        // [ 1, 0 ]
        // [ 0, 1 ]
        // [ 5, 5 ]
        double[][] data = {
            {1.0, 0.0},
            {0.0, 1.0},
            {5.0, 5.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        double[] v = {2.0, 3.0};

        // Expected: [2.0, 3.0, 25.0]
        double[] expected = {2.0, 3.0, 25.0};
        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test
    public void testOperateWithSingleElementMatrix() {
        double[][] data = {{5.0}};
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        double[] v = {2.0};

        double[] expected = {10.0};
        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperateThrowsExceptionWhenVectorLengthIsTooShort() {
        // Matrix 2x2
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        // Vector length 1 instead of 2
        double[] v = {1.0};

        matrix.operate(v);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperateThrowsExceptionWhenVectorLengthIsTooLong() {
        // Matrix 2x2
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        // Vector length 3 instead of 2
        double[] v = {1.0, 2.0, 3.0};

        matrix.operate(v);
    }

    @Test
    public void testOperateWithZeroVector() {
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);
        double[] v = {0.0, 0.0};

        double[] expected = {0.0, 0.0};
        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test
    public void testOperateWithEmptyMatrix() {
        // Depending on implementation, 0x0 matrix might be valid or throw error during construction.
        // Based on provided code, if nRows=0, it returns an empty array.
        RealMatrixImpl matrix = new RealMatrixImpl(0, 0);
        double[] v = {};

        double[] actual = matrix.operate(v);
        Assert.assertEquals(0, actual.length);
    }
}
